// CR-358-P1 | BUG-378 | CR-358-P2 | CR-358-P3 | CR-358-P4 | CR-379 | CR-380: PMS aggregation + booking/check-in + reservation-ops + room-status/tape-chart service
// getInHouseGuests: two-call join — GET_ROOM_LIST + local-reservations enriched on order_id.
// roomService.getRoomList() and roomListTransform are NOT modified — only called.
import { getRoomList } from './roomService';
import roomListTransform from '../transforms/roomListTransform';
import { getLocalReservations, getAiosellRooms, getAiosellStatus, fetchReservations, pushInventory,
         getRates, pushRates, pushInventoryRestrictions, pushRateRestrictions, markNoShow } from './aiosellService'; // BUG-378, CR-358-P2, CR-358-P3, CR-358-P5
import api from '../axios';                                        // CR-358-P2
import { AIOSELL_ENDPOINTS, API_ENDPOINTS } from '../constants';                  // CR-358-P2; CR-364: +API_ENDPOINTS
import aiosellTransform from '../transforms/aiosellTransform';     // CR-358-P2
import roomStatusTransform, { ROOM_MANUAL_STATUSES } from '../transforms/roomStatusTransform'; // CR-358-P4
import { computeRoomGst } from '../../utils/roomGstCalculator';    // BUG-515
const to2dp = (v) => Number(Number(v ?? 0).toFixed(2));            // CR-358-P2

// Date helper — offset from today (YYYY-MM-DD)
const dateOffset = (days) => {
  const d = new Date();
  d.setDate(d.getDate() + days);
  return d.toISOString().slice(0, 10);
};

// CR-358-P3: LOCAL calendar date (not UTC) — restaurant clock. dateOffset() above is UTC and left untouched (BUG-378 consumer).
export const localDate = (offsetDays = 0) => {
  const d = new Date(); d.setDate(d.getDate() + offsetDays);
  return d.toLocaleDateString('en-CA'); // YYYY-MM-DD
};

/**
 * S6 — In-House Guests (BUG-378: enriched with phone, checkinDate, checkoutDate, balance)
 *
 * Step 1: GET_ROOM_LIST → roomListTransform (roomNumber, guestName, phone)
 * Step 2: local-reservations ?start_date=today-60&end_date=today+60
 *         Filter: operational_status === 'in_house'
 *         Join:   rooms[0].order_id === row.parentOrderId
 *         Enrich: checkinDate (checked_in_at), checkoutDate, balance (amount_after_tax), channel
 * Walk-in guests (no AIOSELL reservation): phone from Step 1, dates/balance stay null → "—"
 * Graceful degradation: if Step 2 fails, Step 1 data is still returned (no crash).
 */
export const getInHouseGuests = async ({ roomGstApplicable = false, roomGstSlabs = null } = {}) => { // BUG-515
  // Step 1 — GET_ROOM_LIST (room number, guest name, phone)
  const raw  = await getRoomList();
  const rows = roomListTransform.transformRoomListToRows(raw);

  // Step 2 — local-reservations enrichment
  try {
    const lrData       = await getLocalReservations({ startDate: dateOffset(-60), endDate: dateOffset(60) });
    const reservations = lrData?.data?.reservations ?? lrData?.reservations ?? [];
    const inHouse      = reservations.filter(r => r.operational_status === 'in_house');

    // Build order_id lookup: { [order_id]: { res, room } }
    const lookup = {};
    inHouse.forEach(res => {
      (res.rooms ?? []).forEach(room => {
        if (room.order_id) lookup[room.order_id] = { res, room };
      });
    });

    // Enrich rows with dates, balance, channel
    rows.forEach(row => {
      const match = lookup[row.parentOrderId];
      if (match) {
        row.checkinDate   = match.room.checked_in_at            ?? null; // actual physical check-in (for table column)
        row.bookingCheckin= match.res.checkin                  ?? null; // booking start date (for Avg Nights KPI) — CR-360
        row.checkoutDate  = match.res.checkout                 ?? null;
        // BUG-421: amount_after_tax = initial fallback; overwritten by Step 3 folio call below
        row.balance       = match.res.amount_after_tax != null
                           ? Number(match.res.amount_after_tax) : null;
        row.channel       = match.res.channel                  ?? null;
        row.charge        = match.res.charge                   ?? null;  // BUG-493: expose LR charge.sgst/cgst for Step 3 chargeGst
      }
    });
  } catch {
    // Degraded mode: local-reservations failed (network/auth error).
    // rows still contain roomNumber, guestName, phone from Step 1.
    // checkinDate/checkoutDate/balance will be undefined → page renders "—".
  }

  // BUG-421 Step 3: parallel folio calls for accurate outstanding balance (OD-421-02 approved)
  // Formula: room_price + gst_tax - advance_payment - receive_balance (same as BUG-423 folio page)
  // IMPROVEMENT NOTE: add folio response caching if guest count grows beyond ~20
  try {
    const orderIds = rows.map(r => r.parentOrderId).filter(Boolean);
    if (orderIds.length > 0) {
      const folioResults = await Promise.all(
        orderIds.map(oid =>
          api.post(API_ENDPOINTS.SINGLE_ORDER_NEW, { order_id: Number(oid) })
            .then(res =>
              res?.data?.orders?.order_details_order ||
              res?.data?.order_details_order ||
              (Array.isArray(res?.data?.orders) ? res.data.orders[0] : null) ||
              res?.data?.orders ||
              null
            )
            .catch(() => null) // graceful — one failed call won't break the page
        )
      );
      // Map results by orderId to avoid index mismatch (orderIds may be shorter than rows)
      const resultByOrderId = new Map(
        orderIds.map((oid, i) => [String(oid), folioResults[i]])
      );
      rows.forEach(row => {
        if (!row.parentOrderId) return;
        const raw = resultByOrderId.get(String(row.parentOrderId));
        if (!raw) return;
        const ri = raw.room_info ?? {};
        const rp = Number(ri.room_price      ?? 0);
        const gt = Number(ri.gst_tax         ?? 0);
        const ap = Number(ri.advance_payment ?? 0);
        const rb = Number(ri.receive_balance ?? 0);
        // BUG-491 Sub-A: ri.gst_tax is absent from room_info API; use backend pre-computed
        // balance_payment (already deducts discount) + charge-level GST from booking snapshot
        const bp        = ri.balance_payment != null ? Number(ri.balance_payment) : null;
        const discountRs    = Number(ri.room_discount_amount ?? 0);                                     // BUG-515
        const effectiveRoom = Math.max(0, rp - discountRs);                                             // BUG-515
        const nights        = row.charge?.nights ?? 1;                                                  // BUG-515: available in LR charge snapshot
        const chargeGst     = Number(row.charge?.sgst ?? 0) + Number(row.charge?.cgst ?? 0);
        const effectiveGst  = discountRs > 0 && roomGstApplicable && roomGstSlabs                       // BUG-515
            ? computeRoomGst(roomGstApplicable, roomGstSlabs, effectiveRoom, nights, 1).gstTotal
            : chargeGst;                                                                                  // BUG-515: no discount → rack values correct; fallback if slabs absent
        const roomBalance = bp != null
          ? (bp === 0 ? 0 : Math.max(0, bp + effectiveGst))   // BUG-515: was chargeGst (rack); now effectiveGst
          : Math.max(0, rp + gt - ap - rb - discountRs);       // BUG-515: extracted discountRs

        // BUG-426 OD-426-03: transferred F&B (2 different from room orders)
        const transferredFnb = (raw.associated_order_list ?? []).reduce(
          (s, a) => s + Number(a.order_amount ?? 0), 0
        );

        // BUG-426 OD-426-03: room-native food orders — conditional GST per OD-426-02
        const roomOrdersTotal = (raw.orderDetails ?? [])
          .filter(d => {
            if ((d.food_details?.name ?? '').toLowerCase() === 'check in') return false;
            if (d.food_status === 'cancelled') return false;
            return true;
          })
          .reduce((s, d) => {
            const qty  = Number(d.quantity) || 1;
            const unit = parseFloat(d.unit_price) || (parseFloat(d.price) / qty) || 0;
            // BUG-430: include add-ons in GST base (match orderTransform.js L1900-1904)
            const addonPerUnit = (d.add_ons || []).reduce(
              (s, a) => s + ((parseFloat(a.price) || 0) * (parseFloat(a.quantity) || 1)),
              0
            );
            const amt  = Math.round((unit * qty + addonPerUnit * qty) * 100) / 100;
            if (!roomGstApplicable) return s + amt;
            // BUG-429: match orderTransform GST logic — pre-computed field first, then fallback
            const fd2 = d.food_details || {};
            let gstAmt = Math.round(parseFloat(d.gst_tax_amount || d.tax_amount || 0) * 100) / 100;
            if (!gstAmt) {
              const gstPct = parseFloat(fd2.tax ?? 0);
              if (gstPct > 0) {
                const isInclusive = (fd2.tax_calc || '').toLowerCase() === 'inclusive';
                gstAmt = isInclusive
                  ? Math.round(amt * gstPct / (100 + gstPct) * 100) / 100
                  : Math.round(amt * gstPct / 100 * 100) / 100;
              }
            }
            return s + amt + gstAmt;
          }, 0);

        // BUG-426: store sub-totals separately (OD-426-03 — 2 different) + total balance
        row.transferredFnbBalance = Math.round(transferredFnb * 100) / 100;
        row.roomOrdersBalance     = Math.round(roomOrdersTotal * 100) / 100;
        row.balance               = Math.round((roomBalance + transferredFnb + roomOrdersTotal) * 100) / 100;
        // BUG-515: enrich row with post-discount display values for RowExpansionStub (OD-515-02=c)
        if (discountRs > 0) {
          row.roomDiscountAmount  = discountRs;
          row.effectiveGst        = effectiveGst;
          row.effectiveSgst       = Math.round(effectiveGst / 2 * 100) / 100;
          row.effectiveCgst       = Math.round(effectiveGst / 2 * 100) / 100;
          row.effectiveTotal      = Math.round((effectiveRoom + effectiveGst) * 100) / 100;
          row.effectiveBalanceDue = Math.round(roomBalance * 100) / 100; // BUG-515: = bp + effectiveGst
        }
      });
    }
  } catch {
    // Graceful: if entire Step 3 fails, balance stays as amount_after_tax fallback from Step 2
  }

  return rows;
};

